INTO   TB_BD_BASESUMMRY_ORIGIN (
	   MNGR_REGSTR_PK, UPPER_REGSTR_PK, REGSTR_GB_CD, REGSTR_GB_NM, REGSTR_KD_CD, REGSTR_KD_NM
