INSERT /* homes.batch.mapper.BatchMapper.insertComplex */ 
INTO TB_BD_COMPLEX (
	 CPXNO
	 , CPXGNO
	 , REGSTR_KD_CD
	 , REGSTR_GB_CD
	 , ARCD, LEGCD, BUN, JI
	 , BULD_REGSTR_PK
	 , PLOT_LOC
	 , BULD_NM
	 , BLOCK_NM
	 , ETC_PPS
	 , MAIN_PPS_CD
	 , HSHLD_CO
	 , NW_OD_GB_CD
	 , CREAT_USER_NO
	 , UPDT_USER_NO
) VALUES (
	#{cpxno}
	, #{cpxgno}
	, #{regstrKdCd}
	, #{regstrGbCd}
	, #{arcd}
	, #{legcd}
	, #{bun}
	, #{ji}
	, #{buldRegstrPk}
	, #{plotLoc}
	, #{buldNm}
	, #{blockNm}
	, #{etcPps}
	, #{mainPpsCd}
	, #{hshldCo}
	, #{nwOdGbCd}
	, #{creatUserNo}
	, #{updtUserNo}			
)

	INSERT /* homes.batch.mapper.BatchMapper.insertBatchjob */ 
	INTO TB_CM_BATCHJOB (
		BT_UUID
		, BATCHTY
		, BT_STTUS_CD
        , BT_EXCO 
        , BT_FILENM 
		, BT_ERROR_MSG
		, BT_ST_DT
		, CREAT_USER_NO
		, CREAT_DT
		, UPDT_USER_NO
		, UPDT_DT
	) VALUES(
		#{uuid}
		, #{batchty}
		, #{sttuscd}
		, #{exco}
		, #{filenm}
		, #{message}
		, NOW()
		, 0
		, NOW()
		, 0
		, NOW()
	)

INSERT /* homes.batch.mapper.BatchMapper.insertBaseSummryRawData */ 
INTO TB_BD_BASESUMMRY_RAWDATA (
	CRDE, UUID, NO
	, BULD_REGSTR_PK, REGSTR_GB_CD, REGSTR_KD_CD
	, ARCD, LEGCD, BUN, JI
	, RAW_DATA
	, REGSTR_CR_DE 
) values (
	date_format(NOW(), '%Y%m%d')
	, #{uuid}
	, #{no}
	, #{mngrRegstrPk}
	, #{regstrGbCd}
	, #{regstrKdCd}
	, #{arcd}
	, #{legcd}
	, #{bun}
	, #{ji}
	, #{rawdata}
	, #{regstrCrde}
)

mapper.update:
UPDATE /* homes.batch.mapper.BatchMapper.updateBatchjob */ 
       TB_CM_BATCHJOB
SET    BT_STTUS_CD = #{sttuscd}
       , BT_ED_DT = NOW()
       , BT_EXCO = #{exco}
       , BT_FILENM = #{filenm}
       , BT_ERROR_MSG = #{message}
       , UPDT_USER_NO = 0
       , UPDT_DT = NOW()
WHERE  BT_UUID = #{uuid}

